356	// runExplainAuto resolves a positional target as either a checkpoint ID
357	// (or prefix) or a git commit ref. Ordering: checkpoint path first (which
358	// also handles shadow-branch temp checkpoints), falling back to commit
359	// resolution only on checkpoint.ErrCheckpointNotFound. --generate runs
360	// an ambiguity pre-check to avoid writing a summary to the wrong
361	// checkpoint on short-prefix collisions.
362	func runExplainAuto(ctx context.Context, w, errW io.Writer, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
363		lookup, lookupErr := newExplainCheckpointLookup(ctx, nil)
364		if generate {
365			if err := runExplainAutoAmbiguityGuard(ctx, target, lookup, lookupErr); err != nil {
366				return err
367			}
368		}
369		checkpointErr := runExplainCheckpointWithLookup(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, lookupErr)
370		if checkpointErr == nil {
371			return nil
372		}
373		// Fall back to commit resolution ONLY when nothing (committed or temp)
374		// matched the target. errCannotGenerateTemporaryCheckpoint signals that
375		// we DID match a temp checkpoint but --generate is unsupported for it;
376		// falling back to commit in that case would produce a misleading
377		// "no trailer" error for the shadow-branch commit.
378		if !errors.Is(checkpointErr, checkpoint.ErrCheckpointNotFound) {
379			return checkpointErr
380		}
381		logging.Debug(ctx, "explain auto: checkpoint lookup failed, trying commit fallback",
382			slog.String("target", target),
383			slog.String("checkpoint_error", checkpointErr.Error()))
384	
385		if lookupErr != nil {
386			// Composed message beats errors.Join here — the latter renders
387			// two lines (one per error) and users act on the first/stale one.
388			return fmt.Errorf("no checkpoint matched %q, and commit fallback failed: %w", target, lookupErr)
389		}
390		hash, resolveErr := resolveCommitUnambiguous(lookup.repo, target)
391		if resolveErr != nil {
392			if errors.Is(resolveErr, errAmbiguousCommitPrefix) {
393				return resolveErr
394			}
395			logging.Debug(ctx, "explain auto: git ref resolution failed",
396				slog.String("target", target),
397				slog.String("error", resolveErr.Error()))
398			return fmt.Errorf("no checkpoint or commit found matching %q", target)
399		}
400		commit, commitErr := lookup.repo.CommitObject(hash)
401		if commitErr != nil {
402			return fmt.Errorf("failed to get commit %s: %w", abbreviateCommitHash(lookup.repo, hash), commitErr)
403		}
404		cpID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
405		if !hasCheckpoint {
406			// Side-effect modes must error — silently succeeding would leave
407			// scripts unable to distinguish "done" from "didn't happen".
408			if generate || rawTranscript {
409				return fmt.Errorf("cannot %s: commit %s has no Entire-Checkpoint trailer", generateOrRawLabel(generate), abbreviateCommitHash(lookup.repo, hash))
410			}
411			printNoTrailerMessage(w, lookup.repo, hash)
412			return nil
413		}
414		logging.Debug(ctx, "explain auto: resolved commit to checkpoint via trailer",
415			slog.String("target", target),
416			slog.String("commit", abbreviateCommitHash(lookup.repo, hash)),
417			slog.String("checkpoint_id", cpID.String()))
418		return runExplainCheckpointWithLookup(ctx, w, errW, cpID.String(), noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, nil)
419	}
