421	// runExplainAutoAmbiguityGuard refuses --generate when the positional
422	// target resolves as both a git revision and a committed-checkpoint prefix.
423	// Writing a summary to the wrong checkpoint is destructive; read-only flows
424	// tolerate the same ambiguity by preferring the checkpoint path.
425	//
426	// Best-effort: on repo/list failures we return nil so the main flow
427	// surfaces the real error instead of double-reporting.
428	func runExplainAutoAmbiguityGuard(ctx context.Context, target string, lookup *explainCheckpointLookup, lookupErr error) error {
429		// Targets longer than a checkpoint ID can't prefix-match one.
430		// This is coupled to checkpoint IDs being fixed-width; longer targets
431		// cannot be prefixes of committed checkpoint IDs.
432		if len(target) > id.ShortIDLength {
433			return nil
434		}
435		if lookupErr != nil {
436			logging.Warn(ctx, "explain ambiguity guard degraded: failed to prepare checkpoint lookup",
437				"target", target,
438				"error", lookupErr)
439			return nil
440		}
441		hash, err := lookup.repo.ResolveRevision(plumbing.Revision(target))
442		if err != nil {
443			return nil //nolint:nilerr // target isn't a git ref
444		}
445		if lookup == nil {
446			logging.Warn(ctx, "explain ambiguity guard degraded: checkpoint lookup unavailable",
447				"target", target)
448			return nil
449		}
450		if lookup.committed == nil {
451			logging.Warn(ctx, "explain ambiguity guard degraded: committed checkpoint list unavailable",
452				"target", target)
453			return nil
454		}
455		for _, info := range lookup.committed {
456			if strings.HasPrefix(info.CheckpointID.String(), target) {
457				return fmt.Errorf("ambiguous target %q with --generate: matches both git revision %s and checkpoint prefix (e.g. %s)\nUse --commit <ref> or --checkpoint <id> to disambiguate", target, abbreviateCommitHash(lookup.repo, *hash), info.CheckpointID)
458			}
459		}
460		return nil
461	}
