476	func runExplainCheckpointWithLookup(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, lookup *explainCheckpointLookup, lookupErr error) error {
477		if lookup == nil {
478			var err error
479			lookup, err = newExplainCheckpointLookup(ctx, nil)
480			if err != nil {
481				return err
482			}
483		} else if lookupErr != nil {
484			return lookupErr
485		}
486	
487		// Collect all matching checkpoint IDs to detect ambiguity
488		var matches []id.CheckpointID
489		for _, info := range lookup.committed {
490			if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
491				matches = append(matches, info.CheckpointID)
492			}
493		}
494	
495		// If not found locally, fetch metadata from remote and retry.
496		// This handles the case where we're looking at a checkpoint from another
497		// collaborator's PR whose metadata hasn't been fetched yet.
498		// Try origin first (fast treeless fetch, ~1-2s), then checkpoint_remote
499		// if configured and origin didn't have it. Fetch both v1 and v2 refs.

500		if len(matches) == 0 {
501			anyFetched := FetchMetadataTreeOnly(ctx) == nil
502			if !anyFetched {
503				anyFetched = FetchMetadataFromCheckpointRemote(ctx) == nil
504			}
505			if lookup.preferCheckpointsV2 {
506				v2Fetched := FetchV2MainTreeOnly(ctx) == nil
507				if !v2Fetched {
508					v2Fetched = FetchV2MetadataFromCheckpointRemote(ctx) == nil
509				}
510				anyFetched = anyFetched || v2Fetched
511			}
512			if anyFetched {
513				if freshLookup, freshErr := newExplainCheckpointLookup(ctx, nil); freshErr == nil {
514					lookup = freshLookup
515					if freshCommitted := lookup.committed; freshCommitted != nil {
516						for _, info := range freshCommitted {
517							if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
518								matches = append(matches, info.CheckpointID)
519							}
520						}
521					}
522				}
523			}
524		}
525	
526		var fullCheckpointID id.CheckpointID
527		switch len(matches) {
528		case 0:
529			// Check temp checkpoints BEFORE returning errCannotGenerateTemporaryCheckpoint
530			// so runExplainAuto can distinguish:
531			//   - target matched a real temp checkpoint (sentinel returned, no fallback)
532			//   - target matched nothing (ErrCheckpointNotFound, safe to fall back to commit)
533			// Previously the --generate path bailed before checking temp checkpoints,
534			// which made runExplainAuto fall back to commit resolution for temp
535			// checkpoint SHAs and produce a misleading "no trailer" error.
536			//
537			// --generate and --raw-transcript are mutually exclusive at the flag
538			// layer, so rawTranscript is always false when generate is true; the
539			// direct-to-w write path inside explainTemporaryCheckpoint is not
540			// reachable here and won't leak partial output on error.
541			output, found := explainTemporaryCheckpoint(ctx, w, lookup.repo, lookup.v1Store, checkpointIDPrefix, verbose, full, rawTranscript)
542			if found {
543				if generate {
544					return fmt.Errorf("%w %s (only committed checkpoints supported)", errCannotGenerateTemporaryCheckpoint, checkpointIDPrefix)
545				}
546				outputExplainContent(w, output, noPager)
547				return nil
548			}
549			// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
550			if output != "" {
551				return errors.New(output)
552			}
553			return fmt.Errorf("%w: %s", checkpoint.ErrCheckpointNotFound, checkpointIDPrefix)
554		case 1:
555			fullCheckpointID = matches[0]
556		default:
557			// Ambiguous prefix - show up to 5 examples
558			examples := make([]string, 0, 5)
559			for i := 0; i < len(matches) && i < 5; i++ {
560				examples = append(examples, matches[i].String())
561			}
562			return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
563		}
564	
565		// Resolve store and load checkpoint summary with v2 -> v1 fallback.
566		resolvedReader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, fullCheckpointID, lookup.v1Store, lookup.v2Store, lookup.preferCheckpointsV2)
567		if err != nil {
568			return fmt.Errorf("failed to read checkpoint: %w", err)
569		}
570	
571		// For v2 checkpoints in default display modes (not --full, --generate, or
572		// --raw-transcript), read only from /main — metadata, prompts, and the
573		// compact transcript.jsonl. The raw transcript on /full/* is never needed
574		// for human-readable output and may be unavailable (rotated, not fetched).
575		needsRawTranscript := full || generate || rawTranscript
576		v2Reader, isCheckpointsV2 := resolvedReader.(*checkpoint.V2GitStore)
577	
578		var content *checkpoint.SessionContent
579		if isCheckpointsV2 && !needsRawTranscript {
580			content, err = readV2ContentFromMain(ctx, v2Reader, fullCheckpointID, summary)
581			if err != nil {
582				return fmt.Errorf("failed to read checkpoint content: %w", err)
583			}
584		} else {
585			content, err = readLatestSessionContentForExplain(ctx, resolvedReader, fullCheckpointID, summary)
586			if err != nil {
587				return fmt.Errorf("failed to read checkpoint content: %w", err)
588			}
589		}
590	
591		// Handle summary generation — uses raw transcript.
592		if generate {
593			if err := generateCheckpointSummary(ctx, w, errW, lookup.v1Store, lookup.v2Store, fullCheckpointID, summary, content, force); err != nil {
594				return err
595			}
596			// Reload to get the updated summary. After generation we only need
597			// /main data for display, so use the /main-only path for v2.
598			if isCheckpointsV2 {
599				content, err = readV2ContentFromMain(ctx, v2Reader, fullCheckpointID, summary)
600			} else {
601				content, err = readLatestSessionContentForExplain(ctx, resolvedReader, fullCheckpointID, summary)
602			}
603			if err != nil {
604				return fmt.Errorf("failed to reload checkpoint: %w", err)
605			}
606		}
607	
608		// Handle raw transcript output
609		if rawTranscript {
610			rawLog, _, rawErr := checkpoint.ResolveRawSessionLogForCheckpoint(ctx, fullCheckpointID, lookup.v1Store, lookup.v2Store, lookup.preferCheckpointsV2)
611			if rawErr != nil {
612				return fmt.Errorf("failed to read raw transcript: %w", rawErr)
613			}
614			if len(rawLog) == 0 {
615				return fmt.Errorf("checkpoint %s has no transcript", fullCheckpointID)
616			}
617			// Output raw transcript directly (no pager, no formatting)
618			if _, err = w.Write(rawLog); err != nil {
619				return fmt.Errorf("failed to write transcript: %w", err)
620			}
621			return nil
622		}
623	
624		// Find associated commits (git commits with matching Entire-Checkpoint trailer)
625		associatedCommits, _ := getAssociatedCommits(ctx, lookup.repo, fullCheckpointID, searchAll) //nolint:errcheck // Best-effort
626	
627		// Derive author from the first associated commit (the user who made the commit).
628		// Fall back to GetCheckpointAuthor (walks entire/checkpoints/v1) for checkpoints
629		// not reachable from the current branch.
630		var author checkpoint.Author
631		if len(associatedCommits) > 0 {
632			author = checkpoint.Author{
633				Name:  associatedCommits[0].Author,
634				Email: associatedCommits[0].Email,
635			}
636		} else {
637			author, _ = lookup.v1Store.GetCheckpointAuthor(ctx, fullCheckpointID) //nolint:errcheck // Author is optional
638		}
639	
640		// Format and output
641		output := formatCheckpointOutput(summary, content, fullCheckpointID, associatedCommits, author, verbose, full)
642		outputExplainContent(w, output, noPager)
643		return nil
644	}
