646	func newExplainCheckpointLookup(ctx context.Context, repo *git.Repository) (*explainCheckpointLookup, error) {
647		if repo == nil {
648			var err error
649			repo, err = openRepository(ctx)
650			if err != nil {
651				return nil, fmt.Errorf("not a git repository: %w", err)
652			}
653		}
654	
655		v2URL, err := remote.FetchURL(ctx)
656		if err != nil {
657			logging.Debug(ctx, "explain: using origin for v2 store fetch remote",
658				slog.String("error", err.Error()),
659			)
660			v2URL = ""
661		}
662	
663		lookup := &explainCheckpointLookup{
664			repo:                repo,
665			v1Store:             checkpoint.NewGitStore(repo),
666			v2Store:             checkpoint.NewV2GitStore(repo, v2URL),
667			preferCheckpointsV2: settings.IsCheckpointsV2Enabled(ctx),
668		}
669	
670		committed, err := listCommittedForExplain(ctx, lookup.v1Store, lookup.v2Store, lookup.preferCheckpointsV2)
671		if err != nil {
672			return nil, fmt.Errorf("failed to list checkpoints: %w", err)
673		}
674		lookup.committed = committed
675		return lookup, nil
676	}
