678	func listCommittedForExplain(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, preferCheckpointsV2 bool) ([]checkpoint.CommittedInfo, error) {
679		v1Committed, v1Err := v1Store.ListCommitted(ctx)
680	
681		if !preferCheckpointsV2 {
682			if v1Err != nil {
683				return nil, fmt.Errorf("listing v1 checkpoints: %w", v1Err)
684			}
685			return v1Committed, nil
686		}
687	
688		v2Committed, v2Err := v2Store.ListCommitted(ctx)
689		if v2Err != nil {
690			logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
691				slog.String("error", v2Err.Error()),
692			)
693			if v1Err != nil {
694				return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
695			}
696			return v1Committed, nil
697		}
698	
699		if v1Err != nil {
700			logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
701				slog.String("error", v1Err.Error()),
702			)
703			return v2Committed, nil
704		}
705	
706		// Merge v2 and v1 results so pre-v2 checkpoints remain visible during transition.
707		seen := make(map[id.CheckpointID]struct{}, len(v2Committed))
708		for _, c := range v2Committed {
709			seen[c.CheckpointID] = struct{}{}
710		}
711		committedCheckpoints := make([]checkpoint.CommittedInfo, 0, len(v2Committed)+len(v1Committed))
712		committedCheckpoints = append(committedCheckpoints, v2Committed...)
713		for _, c := range v1Committed {
714			if _, ok := seen[c.CheckpointID]; !ok {
715				committedCheckpoints = append(committedCheckpoints, c)
716			}
717		}
718		return committedCheckpoints, nil
719	}
