721	func readLatestSessionContentForExplain(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*checkpoint.SessionContent, error) {
722		if summary == nil || len(summary.Sessions) == 0 {
723			return nil, checkpoint.ErrCheckpointNotFound
724		}
725	
726		latestIndex := len(summary.Sessions) - 1
727		content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
728		if err != nil {
729			return nil, fmt.Errorf("reading session %d content: %w", latestIndex, err)
730		}
731		return content, nil
732	}
