// resolveCheckpointReaderWithBlobRetry resolves the committed reader and
// summary for a checkpoint. If the initial read fails because tree entries
// exist but the metadata.json blob is missing (the typical aftermath of a
// prior --filter=blob:none fetch), it fetches with full blobs and retries
// once. Mutates *lookup to point at a fresh lookup if a successful retry
// happened, so callers see updated v1Store/v2Store handles.
func resolveCheckpointReaderWithBlobRetry(ctx context.Context, cpID id.CheckpointID, lookup **explainCheckpointLookup) (checkpoint.CommittedReader, *checkpoint.CheckpointSummary, error) {
	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, (*lookup).v1Store, (*lookup).v2Store, (*lookup).preferCheckpointsV2)
	if err == nil {
		return reader, summary, nil
	}
	if !errors.Is(err, checkpoint.ErrCheckpointNotFound) {
		return nil, nil, err
	}
	logging.Debug(ctx, "explain: checkpoint tree entry found but blob read failed, retrying with full fetch",
		slog.String("checkpoint_id", cpID.String()),
		slog.String("error", err.Error()),
	)
	if !fetchFullBlobsForExplain(ctx, (*lookup).preferCheckpointsV2) {
		return nil, nil, err
	}
	freshLookup, freshErr := newExplainCheckpointLookup(ctx)
	if freshErr != nil {
		return nil, nil, err
	}
	*lookup = freshLookup
	return checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, freshLookup.v1Store, freshLookup.v2Store, freshLookup.preferCheckpointsV2)
}

