303	func WalkCheckpointShards(repo *git.Repository, tree *object.Tree, fn func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error) error {
304		for _, bucketEntry := range tree.Entries {
305			if bucketEntry.Mode != filemode.Dir {
306				continue
307			}
308			if len(bucketEntry.Name) != 2 {
309				continue
310			}
311	
312			bucketTree, err := repo.TreeObject(bucketEntry.Hash)
313			if err != nil {
314				continue
315			}
