318				if cpEntry.Mode != filemode.Dir {
319					continue
320				}
321	
322				cpID, err := id.NewCheckpointID(bucketEntry.Name + cpEntry.Name)
323				if err != nil {
324					continue
325				}
326	
327				if err := fn(cpID, cpEntry.Hash); err != nil {
