func resolveCheckpointReaderWithBlobRetry(ctx context.Context, cpID id.CheckpointID, lookup **explainCheckpointLookup) (checkpoint.CommittedReader, *checkpoint.CheckpointSummary, error) {
	logCheckpointBranchHash(ctx, (*lookup).repo, "explain: pre-resolve ref state", cpID, (*lookup).preferCheckpointsV2)

	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, (*lookup).v1Store, (*lookup).v2Store, (*lookup).preferCheckpointsV2)
	if err == nil {
		return reader, summary, nil
	}
	if !errors.Is(err, checkpoint.ErrCheckpointNotFound) {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	logging.Debug(ctx, "explain: checkpoint tree entry found but blob read failed, retrying with full fetch",
		slog.String("checkpoint_id", cpID.String()),
		slog.String("error", err.Error()),
		slog.Bool("prefer_v2", (*lookup).preferCheckpointsV2),
	)
	if !fetchFullBlobsForExplain(ctx, (*lookup).preferCheckpointsV2) {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	freshLookup, freshErr := newExplainCheckpointLookup(ctx)
	if freshErr != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	*lookup = freshLookup

	logCheckpointBranchHash(ctx, freshLookup.repo, "explain: post-fetch ref state", cpID, freshLookup.preferCheckpointsV2)

	reader, summary, retryErr := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, freshLookup.v1Store, freshLookup.v2Store, freshLookup.preferCheckpointsV2)
	if retryErr != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint after blob refetch: %w", retryErr)
	}
	return reader, summary, nil
}

// logCheckpointBranchHash logs the v1 metadata branch ref state and which
// stores observe the checkpoint via direct ListCommitted scans, to help
// diagnose stale ref or blob-availability issues across retries.
func logCheckpointBranchHash(ctx context.Context, repo *git.Repository, label string, cpID id.CheckpointID, preferV2 bool) {
	attrs := []any{slog.String("checkpoint_id", cpID.String())}
	if ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true); err == nil {
		attrs = append(attrs, slog.String("v1_local_hash", ref.Hash().String()))
	} else {
		attrs = append(attrs, slog.String("v1_local_err", err.Error()))
	}
	if ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName), true); err == nil {
		attrs = append(attrs, slog.String("v1_origin_hash", ref.Hash().String()))
	}
	if ref, err := repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true); err == nil {
		attrs = append(attrs, slog.String("v2_main_hash", ref.Hash().String()))
	}
	attrs = append(attrs, slog.Bool("prefer_v2", preferV2))
	logging.Debug(ctx, label, attrs...)
}

