func resolveCheckpointReaderWithBlobRetry(ctx context.Context, cpID id.CheckpointID, lookup **explainCheckpointLookup) (checkpoint.CommittedReader, *checkpoint.CheckpointSummary, error) {
	logCheckpointBranchHash(ctx, (*lookup).repo, "explain: pre-resolve ref state", cpID, (*lookup).preferCheckpointsV2)
	traceCheckpointReadability(ctx, (*lookup).repo, cpID, "pre-resolve")

	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, (*lookup).v1Store, (*lookup).v2Store, (*lookup).preferCheckpointsV2)
	if err == nil {
		return reader, summary, nil
	}
	if !errors.Is(err, checkpoint.ErrCheckpointNotFound) {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	logging.Debug(ctx, "explain: checkpoint tree entry found but blob read failed, retrying with full fetch",
		slog.String("checkpoint_id", cpID.String()),
		slog.String("error", err.Error()),
		slog.Bool("prefer_v2", (*lookup).preferCheckpointsV2),
	)
	if !fetchFullBlobsForExplain(ctx, (*lookup).preferCheckpointsV2) {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	freshLookup, freshErr := newExplainCheckpointLookup(ctx)
	if freshErr != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	*lookup = freshLookup

	logCheckpointBranchHash(ctx, freshLookup.repo, "explain: post-fetch ref state", cpID, freshLookup.preferCheckpointsV2)

	reader, summary, retryErr := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, freshLookup.v1Store, freshLookup.v2Store, freshLookup.preferCheckpointsV2)
	if retryErr != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint after blob refetch: %w", retryErr)
	}
	return reader, summary, nil
}

// traceCheckpointReadability walks the v1 metadata tree manually to pinpoint
// exactly where path resolution for a checkpoint fails — bucket lookup, cp
// tree lookup, metadata.json file entry, or blob contents. This logs at each
// step so we can see whether ReadCommitted's nil/nil result is from a missing
// tree path or a missing blob.
func traceCheckpointReadability(ctx context.Context, repo *git.Repository, cpID id.CheckpointID, label string) {
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		logging.Debug(ctx, "trace: no v1 branch ref", slog.String("label", label), slog.String("error", err.Error()))
		return
	}
	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		logging.Debug(ctx, "trace: cannot read commit", slog.String("label", label), slog.String("hash", ref.Hash().String()), slog.String("error", err.Error()))
		return
	}
	rootTree, err := commit.Tree()
	if err != nil {
		logging.Debug(ctx, "trace: cannot read root tree", slog.String("label", label), slog.String("error", err.Error()))
		return
	}
	idStr := cpID.String()
	bucketName := idStr[:2]
	cpName := idStr[2:]

	bucketEntry, err := rootTree.FindEntry(bucketName)
	if err != nil {
		logging.Debug(ctx, "trace: bucket entry not in root tree", slog.String("label", label), slog.String("bucket", bucketName), slog.String("error", err.Error()))
		return
	}
	logging.Debug(ctx, "trace: bucket entry found", slog.String("label", label), slog.String("bucket", bucketName), slog.String("hash", bucketEntry.Hash.String()), slog.String("mode", bucketEntry.Mode.String()))

	bucketTree, err := repo.TreeObject(bucketEntry.Hash)
	if err != nil {
		logging.Debug(ctx, "trace: bucket TreeObject failed", slog.String("label", label), slog.String("hash", bucketEntry.Hash.String()), slog.String("error", err.Error()))
		return
	}
	logging.Debug(ctx, "trace: bucket tree loaded", slog.String("label", label), slog.Int("entry_count", len(bucketTree.Entries)))

	cpEntry, err := bucketTree.FindEntry(cpName)
	if err != nil {
		logging.Debug(ctx, "trace: cp entry not in bucket tree", slog.String("label", label), slog.String("cp_name", cpName), slog.String("error", err.Error()))
		return
	}
	logging.Debug(ctx, "trace: cp entry found", slog.String("label", label), slog.String("hash", cpEntry.Hash.String()), slog.String("mode", cpEntry.Mode.String()))

	cpTree, err := repo.TreeObject(cpEntry.Hash)
	if err != nil {
		logging.Debug(ctx, "trace: cp TreeObject failed", slog.String("label", label), slog.String("hash", cpEntry.Hash.String()), slog.String("error", err.Error()))
		return
	}
	logging.Debug(ctx, "trace: cp tree loaded", slog.String("label", label), slog.Int("entry_count", len(cpTree.Entries)))

	// Try the path-based lookup that ReadCommitted uses.
	pathTree, err := rootTree.Tree(cpID.Path())
	if err != nil {
		logging.Debug(ctx, "trace: rootTree.Tree(path) failed", slog.String("label", label), slog.String("path", cpID.Path()), slog.String("error", err.Error()))
	} else {
		logging.Debug(ctx, "trace: rootTree.Tree(path) succeeded", slog.String("label", label), slog.String("path", cpID.Path()), slog.String("hash", pathTree.Hash.String()))
	}

	metadataFile, err := cpTree.File(paths.MetadataFileName)
	if err != nil {
		logging.Debug(ctx, "trace: metadata.json entry not found", slog.String("label", label), slog.String("error", err.Error()))
		return
	}
	logging.Debug(ctx, "trace: metadata.json entry found", slog.String("label", label), slog.String("hash", metadataFile.Hash.String()), slog.Int64("size", metadataFile.Size))

	if _, err := metadataFile.Contents(); err != nil {
		logging.Debug(ctx, "trace: metadata.json Contents() failed (blob missing)", slog.String("label", label), slog.String("error", err.Error()))
		return
	}
	logging.Debug(ctx, "trace: metadata.json Contents() succeeded", slog.String("label", label))
}

// logCheckpointBranchHash logs the v1 metadata branch ref state and which
// stores observe the checkpoint via direct ListCommitted scans, to help
// diagnose stale ref or blob-availability issues across retries.
func logCheckpointBranchHash(ctx context.Context, repo *git.Repository, label string, cpID id.CheckpointID, preferV2 bool) {
	attrs := []any{slog.String("checkpoint_id", cpID.String())}
	if ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true); err == nil {
		attrs = append(attrs, slog.String("v1_local_hash", ref.Hash().String()))
	} else {
		attrs = append(attrs, slog.String("v1_local_err", err.Error()))
	}
	if ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName), true); err == nil {
		attrs = append(attrs, slog.String("v1_origin_hash", ref.Hash().String()))
	}
	if ref, err := repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true); err == nil {
		attrs = append(attrs, slog.String("v2_main_hash", ref.Hash().String()))
	}
	attrs = append(attrs, slog.Bool("prefer_v2", preferV2))
	logging.Debug(ctx, label, attrs...)
}

