// Note: deliberately not calling v1Store.SetBlobFetcher here. The
// FetchingTree's per-File() blob fetcher would issue one network
// round-trip per missing blob (and fall back to a full metadata fetch
// per call when the server doesn't support allowReachableSHA1InWant),
// which compounds to minutes for a single explain. Instead, we let
// ReadCommitted fail fast on missing blobs and rely on
// resolveCheckpointReaderWithBlobRetry to do one full fetch and retry.
lookup := &explainCheckpointLookup{
	repo:                repo,
	v1Store:             checkpoint.NewGitStore(repo),
	v2Store:             checkpoint.NewV2GitStore(repo, v2URL),
	preferCheckpointsV2: settings.IsCheckpointsV2Enabled(ctx),
}

