func resolveCheckpointReaderWithBlobRetry(ctx context.Context, cpID id.CheckpointID, lookup **explainCheckpointLookup) (checkpoint.CommittedReader, *checkpoint.CheckpointSummary, error) {
	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, (*lookup).v1Store, (*lookup).v2Store, (*lookup).preferCheckpointsV2)
	if err == nil {
		return reader, summary, nil
	}
	if !errors.Is(err, checkpoint.ErrCheckpointNotFound) {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	logging.Debug(ctx, "explain: checkpoint tree entry found but blob read failed, retrying with full fetch",
		slog.String("checkpoint_id", cpID.String()),
		slog.String("error", err.Error()),
	)
	if !fetchFullBlobsForExplain(ctx, (*lookup).preferCheckpointsV2) {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	freshLookup, freshErr := newExplainCheckpointLookup(ctx)
	if freshErr != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	*lookup = freshLookup
	reader, summary, retryErr := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, freshLookup.v1Store, freshLookup.v2Store, freshLookup.preferCheckpointsV2)
	if retryErr != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint after blob refetch: %w", retryErr)
	}
	return reader, summary, nil
}

// fetchFullBlobsForExplain runs the blob-carrying fetches (checkpoint_remote
// and full origin fetch) for v1 and optionally v2. Used as a recovery path
// when a prior treeless fetch left tree entries but missing blobs. Returns
// true if any fetch succeeded.
func fetchFullBlobsForExplain(ctx context.Context, preferCheckpointsV2 bool) bool {
	anyFetched := false
	if err := FetchMetadataFromCheckpointRemote(ctx); err == nil {
		logging.Debug(ctx, "explain v1 full fetch: checkpoint_remote succeeded")
		anyFetched = true
	} else {
		logging.Debug(ctx, "explain v1 full fetch: checkpoint_remote failed", slog.String("error", err.Error()))
		if err := FetchMetadataBranch(ctx); err == nil {
			logging.Debug(ctx, "explain v1 full fetch: full origin fetch succeeded")
			anyFetched = true
		} else {
			logging.Debug(ctx, "explain v1 full fetch: full origin fetch failed", slog.String("error", err.Error()))
		}
	}
	if preferCheckpointsV2 {
		if err := FetchV2MetadataFromCheckpointRemote(ctx); err == nil {
			logging.Debug(ctx, "explain v2 full fetch: checkpoint_remote succeeded")
			anyFetched = true
		} else {
			logging.Debug(ctx, "explain v2 full fetch: checkpoint_remote failed", slog.String("error", err.Error()))
			if err := FetchV2MainRef(ctx); err == nil {
				logging.Debug(ctx, "explain v2 full fetch: full origin fetch succeeded")
				anyFetched = true
			} else {
				logging.Debug(ctx, "explain v2 full fetch: full origin fetch failed", slog.String("error", err.Error()))
			}
		}
	}
	return anyFetched
}

