// fetchBlobsByHashNoFallback fetches specific blob objects by hash without
// the full-fetch fallback that FetchBlobsByHash performs. Explain reads only
// a handful of blobs per checkpoint, so a single failed fetch should NOT
// trigger a multi-minute full clone of the metadata branch — we'd rather
// surface the error and let the user retry.
func fetchBlobsByHashNoFallback(ctx context.Context, hashes []plumbing.Hash) error {
	if len(hashes) == 0 {
		return nil
	}
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	fetchTarget := resolveCheckpointFetchTarget(ctx)
	hashStrs := make([]string, len(hashes))
	for i, h := range hashes {
		hashStrs[i] = h.String()
	}
	if err := remote.FetchBlobs(ctx, fetchTarget, hashStrs); err != nil {
		return fmt.Errorf("fetch %d blob(s) by hash from %s: %w", len(hashes), fetchTarget, err)
	}
	return nil
}

func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
	args := []string{"fetch", "--no-tags", "--no-write-fetch-head"}
	// In partial-clone mode (filtered_fetches=true) git enforces filter
	// semantics on every fetch and rejects bare SHA fetches with
	// "did not send all necessary objects". Adding --filter=blob:none
	// switches the request to the partial-clone protocol; the server
	// still sends the SHAs we ask for via "want", it just doesn't send
	// extra reachable blobs we didn't request — which is exactly what
	// we want here.
	if settings.IsFilteredFetchesEnabled(ctx) {
		args = append(args, "--filter=blob:none")
	}
	args = append(args, remote)
	args = append(args, hashes...)

	cmd := newCommand(ctx, args...)
	disableTerminalPrompt(cmd)
	output, err := cmd.CombinedOutput()
	if err != nil {
