// fetchV1MetadataWithFallback runs the same fetch fallback chain as
// resume.getMetadataTree to make the v1 entire/checkpoints/v1 branch
// available locally: checkpoint_remote (preferred when configured), then
// treeless origin fetch, then full origin fetch. Returns true if any fetch
// succeeded — callers should re-read the metadata after a successful fetch.
func fetchV1MetadataWithFallback(ctx context.Context) bool {
	err := FetchMetadataFromCheckpointRemote(ctx)
	if err == nil {
		logging.Debug(ctx, "explain v1 fetch: checkpoint_remote succeeded")
		return true
	}
	logging.Debug(ctx, "explain v1 fetch: checkpoint_remote failed", slog.String("error", err.Error()))

	err = FetchMetadataTreeOnly(ctx)
	if err == nil {
		logging.Debug(ctx, "explain v1 fetch: treeless origin fetch succeeded")
		return true
	}
	logging.Debug(ctx, "explain v1 fetch: treeless origin fetch failed", slog.String("error", err.Error()))

	err = FetchMetadataBranch(ctx)
	if err == nil {
		logging.Debug(ctx, "explain v1 fetch: full origin fetch succeeded")
		return true
	}
	logging.Debug(ctx, "explain v1 fetch: full origin fetch failed", slog.String("error", err.Error()))
	return false
}

// fetchV2MetadataWithFallback runs the v2 equivalent of
// fetchV1MetadataWithFallback against the v2 /main ref: checkpoint_remote
// first, then treeless origin fetch, then full origin fetch.
func fetchV2MetadataWithFallback(ctx context.Context) bool {
	err := FetchV2MetadataFromCheckpointRemote(ctx)
	if err == nil {
		logging.Debug(ctx, "explain v2 fetch: checkpoint_remote succeeded")
		return true
	}
	logging.Debug(ctx, "explain v2 fetch: checkpoint_remote failed", slog.String("error", err.Error()))

	err = FetchV2MainTreeOnly(ctx)
	if err == nil {
		logging.Debug(ctx, "explain v2 fetch: treeless origin fetch succeeded")
		return true
	}
	logging.Debug(ctx, "explain v2 fetch: treeless origin fetch failed", slog.String("error", err.Error()))

	err = FetchV2MainRef(ctx)
	if err == nil {
		logging.Debug(ctx, "explain v2 fetch: full origin fetch succeeded")
		return true
	}
	logging.Debug(ctx, "explain v2 fetch: full origin fetch failed", slog.String("error", err.Error()))
	return false
}

// prefetchCheckpointBlobs walks the metadata-branch tree down to the
// checkpoint subtree, collects every locally-missing blob in one pass, and
// fetches them all in a single `git fetch-pack <url> <hash1> <hash2>...`
// invocation via FetchBlobsByHash. Best-effort — failure is logged and the
// read path falls back to the FetchingTree's per-File fetcher.
//
// Without this, every File() inside the read path could trigger its own
// network round-trip for a single blob, and SSH handshake overhead would
// dominate the request time.
func prefetchCheckpointBlobs(ctx context.Context, repo *git.Repository, cpID id.CheckpointID) {
	rootTree, err := loadV1MetadataRootTree(repo)
	if err != nil {
		logging.Debug(ctx, "explain prefetch: cannot load v1 root tree", slog.String("error", err.Error()))
		return
	}
	cpSubtree, err := rootTree.Tree(cpID.Path())
	if err != nil {
		logging.Debug(ctx, "explain prefetch: cp subtree not found", slog.String("checkpoint_id", cpID.String()), slog.String("error", err.Error()))
		return
	}
	ft := checkpoint.NewFetchingTree(ctx, cpSubtree, repo.Storer, FetchBlobsByHash)
	prefetched, err := ft.PreFetch()
	if err != nil {
		logging.Debug(ctx, "explain prefetch: PreFetch failed", slog.String("checkpoint_id", cpID.String()), slog.String("error", err.Error()))
		return
	}
	if prefetched > 0 {
		logging.Debug(ctx, "explain prefetch: blobs fetched in one round-trip",
			slog.String("checkpoint_id", cpID.String()),
			slog.Int("blob_count", prefetched),
		)
	}
}

// loadV1MetadataRootTree returns the root tree of the local v1 metadata
// branch (or its remote-tracking fallback). Used by prefetchCheckpointBlobs
// to navigate to a checkpoint's subtree without going through the v1Store
// (which would trigger blob reads).
func loadV1MetadataRootTree(repo *git.Repository) (*object.Tree, error) {
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName), true)
		if err != nil {
			return nil, fmt.Errorf("v1 metadata branch ref not found: %w", err)
		}
	}
	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("read v1 metadata commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("read v1 metadata tree: %w", err)
	}
	return tree, nil
}

